0 arch/x86_64/uefi/*
0 arch/aarch64/uefi/*
0 docs/*
0 data/*
0 keys/*
0 prebuilt/*
0 include/*
0 wire.*   # проводка обратных вызовов между уровнями
0 klog.*
0 uart.*
0 earlycon.*
0 crashdump.*
