1 arch/*/cpu.h   # обёртки команд процессора (cpuid, rdtsc, cli): платформа, не драйверы
3 scale.*   # чистые функции выбора размеров таблиц по числу ядер и ОЗУ, без зависимостей: нужны планировщику и процессам
3 kdrv_sysnr.*   # номера системных вызовов драйверов Ring 3 (только enum)
3 userlog.*   # построчный вывод программ: чистые функции без зависимостей
3 usbmsc_fs.*   # тома FAT накопителей USB: usbmsc.c (ур.2) отдаёт блочное устройство, монтирует эта сторона
3 kfs.*   # собственная файловая система ядра (ARCHITECTURE: подсистема ядра рядом с blk): опирается на blk, heap, kmutex; её читают Разум и службы
3 store.*   # запись опыта на диск и crc32: только blk
3 fat.*   # FAT поверх blk и kfs
3 vfs.*   # точки монтирования kfs и FAT
3 caps.*
3 trust.*
3 crypto.*
3 sha256.*
3 pk.*
